function taigaCapMat(map, U, rough = 0.9){
  const m = new THREE.MeshStandardMaterial({ vertexColors:true, map, roughness:rough });
  m.onBeforeCompile = sh => {
    sh.uniforms.uCap = U;
    sh.vertexShader = 'uniform float uCap; varying float vCap;\n' + sh.vertexShader.replace('#include <begin_vertex>', `#include <begin_vertex>
      #ifdef USE_INSTANCING
        vec3 wn = normalize(mat3(modelMatrix)*mat3(instanceMatrix)*objectNormal);
      #else
        vec3 wn = normalize(mat3(modelMatrix)*objectNormal);
      #endif
      vCap = smoothstep(0.62 - 0.4*uCap, 0.86 - 0.3*uCap, wn.y + 0.12*sin(position.x*9.0 + position.z*7.0) + 0.06*sin(position.x*23.0 - position.y*17.0));
      transformed += objectNormal*vCap*uCap*0.16;`);
    sh.fragmentShader = 'varying float vCap;\n' + sh.fragmentShader.replace('#include <color_fragment>', `#include <color_fragment>
        diffuseColor.rgb = mix(diffuseColor.rgb, vec3(0.9, 0.93, 0.98), vCap);`)
      .replace('#include <roughnessmap_fragment>', '#include <roughnessmap_fragment>\n        roughnessFactor = mix(roughnessFactor, 0.78, vCap);');
  };
  m.customProgramCacheKey = () => 'taigaCap';
  return m;
}

